INSERT INTO cms.faq (id, question_en, question_ar, answer_en, answer_ar, category, is_published, sort_order, created_at) VALUES ('faq-6', 'Do you offer annual SLA retainers?', 'هل تتوفر عقود صيانة وتشغيل سنوية؟', 'Contact Al-Manar Films at studio@almanarfilms.bh or submit an inquiry online; our team responds within one business day.', 'يمكنكم التواصل عبر studio@almanarfilms.bh أو إرسال طلب إلكتروني وسيرد فريق أفلام المنار خلال يوم عمل واحد.', 'general', true, 6, now()) ON CONFLICT (id) DO NOTHING;
